verification_commands.ac5:
set -u
command -v python3 >/dev/null 2>&1 || { echo "ac5 RED: python3 missing"; exit 1; }
RD=README.md
TM=docs/criteria/scoring_map/telemetry.md
DV=backend/scripts/docs_verification.py
RP=docs/criteria/docs_verification.md
for f in "$RD" "$TM" "$DV" "$RP"; do test -f "$f" || { echo "ac5 RED: $f missing"; exit 1; }; done
python3 - "$RD" "$TM" "$DV" "$RP" <<'PYEOF' || exit 1
import hashlib, json, re, sys
rd = open(sys.argv[1], "rb").read().replace(b"\r\n", b"\n").decode("utf-8", "replace")
tm = open(sys.argv[2], encoding="utf-8", errors="replace").read().replace("\r\n", "\n")
dv = open(sys.argv[3], encoding="utf-8", errors="replace").read().replace("\r\n", "\n")
rp = open(sys.argv[4], encoding="utf-8", errors="replace").read().replace("\r\n", "\n")
PRE_CHAIN_README = "a5e22eecd13a38a23129825de11d3c2ef83f9792c011a342f416e670fb73a4d9"
fail = []
# --- README row 12, located by CELLS not by line number (t122 moves the table).
row = None
for ln in rd.split("\n"):
    cells = [c.strip() for c in ln.strip().split("|")]
    if len(cells) >= 4 and cells[1] == "12" and "On-Call Agent" in cells[2]:
        row = cells
        break
if row is None:
    fail.append("no criteria row with cell '12' naming On-Call Agent was found in README.md - the row is the claim carrier and it must be locatable by content")
else:
    if row[3] != "2/2":
        fail.append("README row 12 scores %r, not '2/2' - this card is the drill half; leaving 1/2 says the drill never landed (RED at base by design: at 463628d the cell read 1/2 on line 286)" % row[3])
    if "docs/criteria/scoring_map/telemetry.md" not in " ".join(row):
        fail.append("README row 12 no longer cites docs/criteria/scoring_map/telemetry.md - the scoring map is the cited deep dive for this rubric point")
    if "oncall_drill_verification.md" not in " ".join(row):
        fail.append("README row 12 does not cite docs/criteria/oncall_drill_verification.md - a 2/2 claim must point at the drill record that earned it, exactly as row 11 points at its drill")
# --- telemetry.md On-Call section: measured pinned SECTION (no generator - t123's ruling).
m = re.search(r"^## On-Call Agent\n(.*?)(?=^## |\Z)", tm, re.S | re.M)
if not m:
    fail.append("telemetry.md has no '## On-Call Agent' section")
else:
    sec = m.group(1)
    if "- Claim: 2/2" not in sec:
        fail.append("the telemetry On-Call claim is not '- Claim: 2/2' - the carrier and the scoring map must agree or the claim is a README-only inflation")
    if "oncall_drill_verification.md" not in sec:
        fail.append("the telemetry On-Call section does not cite the drill carrier - the 2/2 claim must name its evidence")
    if not re.search(r"- (Gap|Reason|Classification):", sec):
        fail.append("the On-Call Gap/Reason/Classification line is gone - the honest half of the claim (documented rehearsal, human-operated runbooks, no live container operation) must stay stated")
    if "documented" not in sec.lower():
        fail.append("the On-Call section never says the drill is DOCUMENTED - claiming a live remediation this environment cannot perform is the honesty failure this fence exists to catch")
# --- triple-pin chain: constants, live README, regenerated report all agree in THIS commit.
cd = re.search(r'^README_DIGEST = "([0-9a-f]{64})"', dv, re.M)
cl = re.search(r"^README_LINES = ([0-9]+)", dv, re.M)
if not cd or not cl:
    fail.append("README_DIGEST / README_LINES could not be parsed from docs_verification.py - the t71/t72 pin constants are the chain's middle link")
else:
    digest = hashlib.sha256(rd.encode("utf-8")).hexdigest()
    lines = len(rd.split("\n"))
    if digest != cd.group(1):
        fail.append("README cr-stripped digest %s != README_DIGEST %s - the row-12 edit and the constant re-pin must land in the SAME commit (the t121/t122 triple-pin chain)" % (digest[:12], cd.group(1)[:12]))
    if lines != int(cl.group(1)):
        fail.append("README line count %d != README_LINES %s - the row-12 edit must be in-place (one line rewritten), never a row inserted" % (lines, cl.group(1)))
    if "README_MEASURE PASS lines=%s digest=%s" % (cl.group(1), cd.group(1)) not in rp:
        fail.append("the regenerated report does not carry 'README_MEASURE PASS lines=%s digest=%s' - docs_verification.md must be REGENERATED in the same commit as the row edit and the constant re-pin, not hand-edited" % (cl.group(1), cd.group(1)[:12]))
    # NEGATIVE CONTROL: forcing row 12's score back to 1/2 must break the digest equality, which
    # proves the digest leg measures the row edit rather than a coincidental file state.
    if row is not None:
        forced = rd.replace("| " + row[3] + " |", "| 1/2 |", 1)
        if hashlib.sha256(forced.encode("utf-8")).hexdigest() == cd.group(1):
            fail.append("NEGATIVE CONTROL FAILED - the README_DIGEST constant matches the README with row 12 back at 1/2, so the row never moved")
    if digest == PRE_CHAIN_README:
        fail.append("the README digest is still the pre-chain pin %s - no row-12 edit happened at all" % PRE_CHAIN_README[:12])
# --- leg 227 discipline: this card writes ZERO index bytes.
idx = json.load(open("docs/state/merge_test_index.json", encoding="utf-8"))["tests"]
txt227 = idx[227]["command"]
if "T124" in txt227:
    fail.append("leg 227 carries a t124 placeholder - 227 is NOT this card's to re-pin (t122's placeholder amendment is the pending one)")
if not ("a5e22eecd13a38a23129825de11d3c2ef83f9792c011a342f416e670fb73a4d9" in txt227 or "T122_README_CR_STRIPPED_DIGEST_64HEX" in txt227):
    fail.append("leg 227 carries neither the pre-chain README pin nor t122's pending placeholder - the README custody chain moved outside this card's knowledge; stop and re-groom rather than re-pinning here")
if fail:
    sys.stdout.write("ac5 evidence: " + "; ".join(fail) + "\n")
    print("ac5 RED: the 2/2 claim is not a sound measured claim in both carriers (%d defects)" % len(fail))
    sys.exit(1)
sys.stdout.write("ac5 evidence: README row 12 (located by cells) reads 2/2, names On-Call Agent, cites the scoring map AND the drill carrier; telemetry.md's On-Call section re-claims Claim 2/2 with its honest Gap/Reason line and the documented disclosure; the triple-pin chain agrees (README digest/lines == docs_verification.py constants == regenerated README_MEASURE PASS line); leg 227 is untouched and its pending state is disclosed; the pre-chain digest %s is gone\n" % PRE_CHAIN_README[:12])
PYEOF
echo "ac5 GREEN: the On-Call claim is a measured 2/2 in README and telemetry.md, the README/constants/report triple-pin chain agrees in this commit, and leg 227 was left for its own pending amendment"
